fn frame(t: i32) {
    host::display::clear(0x050208);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let mut px: i32 = 0;
    let mut py: i32 = 0;
    let mut a: i32 = 0;
    while a <= 256 {
        let x: i32 = cx + (108 * host::math::cos(a)) / 256 + (56 * host::math::cos(a * 5 + t)) / 256;
        let y: i32 = cy + (108 * host::math::sin(a)) / 256 + (56 * host::math::sin(a * 5 + t)) / 256;
        if a > 0 {
            host::display::draw_line(px, py, x, y, 0x66ffcc);
        }
        px = x;
        py = y;
        a = a + 2;
    }
    host::display::present();
}
